/** SINH TỰ ĐỘNG bởi scratchpad/agt/lab/ch4/tao-ma.mjs (2026-11-24) — mã lab + output THẬT (Node 22.22.2, git 2.55.0, Java 25, PostgreSQL 16, GCC 16.1.1). Đừng sửa tay. */
export const MA = {
 "apiV1": "// DatLichApi.java — PR LF-23 \"Lịch của tôi\" (S23) của C1, bản MỞ PR. Tối giản controller bằng JDK HttpServer + JDBC\n// (chạy không cần build); trong Spring Boot là @GetMapping + JdbcTemplate — lỗi y hệt. Người đăng nhập: header X-Nguoi-Dung\n// (thay cho phiên đăng nhập, để lab ngắn).\nimport com.sun.net.httpserver.*;\nimport java.net.InetSocketAddress;\nimport java.nio.charset.StandardCharsets;\nimport java.sql.*;\n\npublic class DatLichApi {\n  static final String DB = \"jdbc:postgresql://\" + System.getenv().getOrDefault(\"PG\", \"127.0.0.1:45434\") + \"/postgres?user=postgres\";\n\n  public static void main(String[] a) throws Exception {\n    var s = HttpServer.create(new InetSocketAddress(\"127.0.0.1\", Integer.parseInt(a[0])), 0);\n    s.createContext(\"/api/dat-lich/\", DatLichApi::xuLy);\n    s.start();\n    System.out.println(\"DatLichApi v1 chạy ở cổng \" + a[0]);\n  }\n\n  static void xuLy(HttpExchange x) throws java.io.IOException {\n    String uid = x.getRequestHeaders().getFirst(\"X-Nguoi-Dung\");\n    String duong = x.getRequestURI().getPath().substring(\"/api/dat-lich/\".length());\n    String q = x.getRequestURI().getQuery();\n    try (Connection c = DriverManager.getConnection(DB); Statement st = c.createStatement()) {\n      ResultSet r;\n      if (duong.equals(\"tim\")) {                       // GET /api/dat-lich/tim?lab=LAB-1 — lịch của tôi ở một lab\n        String lab = java.net.URLDecoder.decode(q.substring(4), StandardCharsets.UTF_8);\n        r = st.executeQuery(\"select id, nguoi_dat_id, lab, bat_dau, ghi_chu from dat_lich where nguoi_dat_id = \" + uid\n            + \" and lab = '\" + lab + \"' order by id\");\n      } else {                                         // GET /api/dat-lich/{id} — chi tiết một lịch\n        r = st.executeQuery(\"select id, nguoi_dat_id, lab, bat_dau, ghi_chu from dat_lich where id = \" + Long.parseLong(duong));\n      }\n      tra(x, 200, json(r));\n    } catch (Exception e) {\n      tra(x, 500, \"{\\\"loi\\\":\\\"\" + e.getMessage().replace(\"\\\"\", \"'\").replace(\"\\n\", \" \") + \"\\\"}\");\n    }\n  }\n\n  static String json(ResultSet r) throws SQLException {\n    var b = new StringBuilder(\"[\");\n    while (r.next()) b.append(b.length() > 1 ? \",\" : \"\").append(String.format(\"{\\\"id\\\":%d,\\\"nguoi\\\":%d,\\\"lab\\\":\\\"%s\\\",\\\"bat_dau\\\":\\\"%s\\\",\\\"ghi_chu\\\":\\\"%s\\\"}\",\n        r.getLong(1), r.getLong(2), r.getString(3), r.getString(4), r.getString(5)));\n    return b.append(\"]\").toString();\n  }\n\n  static void tra(HttpExchange x, int ma, String body) throws java.io.IOException {\n    byte[] b = body.getBytes(StandardCharsets.UTF_8);\n    x.getResponseHeaders().set(\"Content-Type\", \"application/json; charset=utf-8\");\n    x.sendResponseHeaders(ma, b.length);\n    x.getResponseBody().write(b);\n    x.close();\n  }\n}",
 "apiV2": "// DatLichApi.java — PR LF-23 \"Lịch của tôi\" (S23) của C1, bản SAU REVIEW. Tối giản controller bằng JDK HttpServer + JDBC\n// (chạy không cần build); trong Spring Boot là @GetMapping + JdbcTemplate — cách sửa y hệt. Người đăng nhập: header X-Nguoi-Dung\n// (thay cho phiên đăng nhập, để lab ngắn).\nimport com.sun.net.httpserver.*;\nimport java.net.InetSocketAddress;\nimport java.nio.charset.StandardCharsets;\nimport java.sql.*;\n\npublic class DatLichApi {\n  static final String DB = \"jdbc:postgresql://\" + System.getenv().getOrDefault(\"PG\", \"127.0.0.1:45434\") + \"/postgres?user=postgres\";\n\n  public static void main(String[] a) throws Exception {\n    var s = HttpServer.create(new InetSocketAddress(\"127.0.0.1\", Integer.parseInt(a[0])), 0);\n    s.createContext(\"/api/dat-lich/\", DatLichApi::xuLy);\n    s.start();\n    System.out.println(\"DatLichApi v2 chạy ở cổng \" + a[0]);\n  }\n\n  static void xuLy(HttpExchange x) throws java.io.IOException {\n    String duong = x.getRequestURI().getPath().substring(\"/api/dat-lich/\".length());\n    String q = x.getRequestURI().getQuery();\n    try (Connection c = DriverManager.getConnection(DB)) {\n      long uid;\n      try { uid = Long.parseLong(x.getRequestHeaders().getFirst(\"X-Nguoi-Dung\")); }\n      catch (Exception e) { tra(x, 401, \"{\\\"loi\\\":\\\"chưa đăng nhập\\\"}\"); return; }\n      boolean quanLy = vai(c, uid).equals(\"QUAN_LY_LAB\");\n      PreparedStatement p;\n      if (duong.equals(\"tim\") && q != null && q.startsWith(\"lab=\")) {   // lịch của TÔI ở một lab — tham số, không nối chuỗi\n        p = c.prepareStatement(\"select id, nguoi_dat_id, lab, bat_dau, ghi_chu from dat_lich where nguoi_dat_id = ? and lab = ? order by id\");\n        p.setLong(1, uid);\n        p.setString(2, java.net.URLDecoder.decode(q.substring(4), StandardCharsets.UTF_8));\n      } else if (duong.matches(\"\\\\d{1,18}\")) {         // chi tiết: chỉ chủ lịch hoặc quản lý lab (BR-07)\n        p = c.prepareStatement(\"select id, nguoi_dat_id, lab, bat_dau, ghi_chu from dat_lich where id = ? and (nguoi_dat_id = ? or ?)\");\n        p.setLong(1, Long.parseLong(duong));\n        p.setLong(2, uid);\n        p.setBoolean(3, quanLy);\n      } else { tra(x, 400, \"{\\\"loi\\\":\\\"yêu cầu không hợp lệ\\\"}\"); return; }\n      String kq = json(p.executeQuery());\n      if (!duong.equals(\"tim\") && kq.equals(\"[]\")) { tra(x, 404, \"{\\\"loi\\\":\\\"không tìm thấy\\\"}\"); return; }   // 404, không 403: không lộ id có tồn tại\n      tra(x, 200, kq);\n    } catch (SQLException e) {\n      System.err.println(\"Lỗi CSDL: \" + e.getMessage());                 // chi tiết vào log máy chủ, không trả cho người gọi\n      tra(x, 500, \"{\\\"loi\\\":\\\"lỗi hệ thống\\\"}\");\n    }\n  }\n\n  static String vai(Connection c, long uid) throws SQLException {\n    var p = c.prepareStatement(\"select vai from nguoi_dung where id = ?\");\n    p.setLong(1, uid);\n    var r = p.executeQuery();\n    return r.next() ? r.getString(1) : \"\";\n  }\n\n  static String json(ResultSet r) throws SQLException {\n    var b = new StringBuilder(\"[\");\n    while (r.next()) b.append(b.length() > 1 ? \",\" : \"\").append(String.format(\"{\\\"id\\\":%d,\\\"nguoi\\\":%d,\\\"lab\\\":\\\"%s\\\",\\\"bat_dau\\\":\\\"%s\\\",\\\"ghi_chu\\\":\\\"%s\\\"}\",\n        r.getLong(1), r.getLong(2), e(r.getString(3)), e(r.getString(4)), e(r.getString(5))));\n    return b.append(\"]\").toString();\n  }\n\n  static String e(String s) {                          // thoát chuỗi JSON: ghi chú do người dùng gõ có thể chứa \" hoặc xuống dòng\n    if (s == null) return \"\";\n    return s.replace(\"\\\\\", \"\\\\\\\\\").replace(\"\\\"\", \"\\\\\\\"\").replace(\"\\n\", \"\\\\n\").replace(\"\\r\", \"\\\\r\");\n  }\n\n  static void tra(HttpExchange x, int ma, String body) throws java.io.IOException {\n    byte[] b = body.getBytes(StandardCharsets.UTF_8);\n    x.getResponseHeaders().set(\"Content-Type\", \"application/json; charset=utf-8\");\n    x.sendResponseHeaders(ma, b.length);\n    x.getResponseBody().write(b);\n    x.close();\n  }\n}",
 "duLieu": "create table nguoi_dung (id bigint primary key, email varchar(120) not null unique, vai varchar(20) not null);\ncreate table dat_lich (id bigint primary key, nguoi_dat_id bigint not null references nguoi_dung(id), lab varchar(20) not null,\n  bat_dau timestamp not null, ghi_chu varchar(200));\ninsert into nguoi_dung values (2201, 'an.sv@fpt.edu.vn', 'SINH_VIEN'), (2202, 'binh.sv@fpt.edu.vn', 'SINH_VIEN'),\n  (2203, 'chi.sv@fpt.edu.vn', 'SINH_VIEN'), (901, 'ql.lab@fpt.edu.vn', 'QUAN_LY_LAB');\ninsert into dat_lich values\n  (101, 2201, 'LAB-1', '2027-03-02 09:00', 'Đo mạch khuếch đại'),\n  (102, 2202, 'LAB-1', '2027-03-02 13:00', 'Làm lại bài thi trượt — xin đừng báo nhóm'),\n  (103, 2203, 'LAB-2', '2027-03-03 08:00', 'Nhóm đồ án IoT, SĐT 09xx xxx 123'),\n  (104, 2201, 'LAB-2', '2027-03-04 10:00', 'Mang theo \"bộ kit\" số 3');",
 "gotoFail": "/* goto-fail.c — dựng lại hình dạng lỗi \"goto fail\" (Apple, CVE-2014-1266) ở mức tối giản để thấy vì sao\n   mắt người review lướt qua mà không thấy. Không phải mã của Apple: chỉ giữ cấu trúc if … goto fail; lặp dòng. */\n#include <stdio.h>\n#include <string.h>\n\nstatic int kiem(const char *buoc, int ok) { printf(\"  kiểm %s → %s\\n\", buoc, ok ? \"đạt\" : \"TRƯỢT\"); return ok ? 0 : -1; }\n\nstatic int xac_minh(const char *chu_ky) {\n    int err;\n    if ((err = kiem(\"băm\", 1)) != 0)\n        goto fail;\n    if ((err = kiem(\"độ dài\", 1)) != 0)\n        goto fail;\n        goto fail;\n    if ((err = kiem(\"chữ ký\", strcmp(chu_ky, \"CHU-KY-THAT\") == 0)) != 0)\n        goto fail;\nfail:\n    return err;\n}\n\nint main(void) {\n    printf(\"chữ ký thật:\\n\");  printf(\"  ⇒ %s\\n\", xac_minh(\"CHU-KY-THAT\") == 0 ? \"CHẤP NHẬN\" : \"từ chối\");\n    printf(\"chữ ký GIẢ:\\n\");   printf(\"  ⇒ %s\\n\", xac_minh(\"CHU-KY-GIA\") == 0 ? \"CHẤP NHẬN\" : \"từ chối\");\n    return 0;\n}",
 "soatDiff": "// soat-diff.mjs — người review chạy TRƯỚC khi đọc PR: máy bắt phần máy bắt được trên các dòng THÊM của diff,\n// rồi in phần checklist mà chỉ NGƯỜI soát được (đối chiếu tiêu chí chấp nhận, quyền, dữ liệu).\n// Dùng: git diff origin/main... | node soat-diff.mjs      hoặc   node soat-diff.mjs <tệp.diff>\nimport fs from 'node:fs';\nconst diff = fs.readFileSync(process.argv[2] ?? 0, 'utf8').split('\\n');\nconst LUAT = [   // [mức, mẫu, lời nhắc] — mẫu đơn giản, cố ý: bắt nhiều hơn là sót; người review quyết định\n  ['blocking', /\"(select|insert|update|delete)\\b[^\"]*\"\\s*\\+|\\+\\s*\"[^\"]*'\"\\s*\\+|'\"\\s*\\+\\s*\\w+\\s*\\+\\s*\"'/i, 'nối chuỗi vào câu SQL ⇒ SQL injection; dùng PreparedStatement / tham số ?'],\n  ['blocking', /\\.createStatement\\(\\)/, 'Statement thường: mọi giá trị phải đi qua tham số — xem lại các câu SQL dùng nó'],\n  ['blocking', /getMessage\\(\\)[^;]*\\b(tra|send|write|body|ResponseEntity)|\\b(tra|send|write|body)\\([^;]*getMessage\\(\\)/, 'trả thông báo lỗi nội bộ cho người gọi ⇒ lộ câu SQL/cấu trúc bảng; ghi log, trả câu chung'],\n  ['blocking', /(password|passwd|secret|api[_-]?key|token)\\s*[=:]\\s*[\"'][^\"']{6,}/i, 'có vẻ là bí mật viết thẳng trong mã'],\n  ['non-blocking', /catch\\s*\\(\\s*(Exception|Throwable)\\s+\\w+\\s*\\)/, 'bắt Exception chung — có nuốt lỗi lập trình (NullPointer, NumberFormat) thành 500 không?'],\n  ['non-blocking', /String\\.format\\(\"\\{\\\\\"/, 'tự ghép JSON bằng String.format — giá trị chuỗi có được thoát \" và xuống dòng không?'],\n  ['non-blocking', /System\\.(out|err)\\.print|console\\.log|printStackTrace\\(\\)/, 'in ra console — dùng logger của dự án'],\n  ['non-blocking', /\\b(TODO|FIXME|XXX)\\b/, 'còn TODO — có ticket chưa?'],\n];\nlet tep = '', dong = 0, so = 0; const bat = [];\nfor (const l of diff) {\n  if (l.startsWith('+++ ')) { tep = l.slice(4).replace(/^b\\//, ''); continue; }\n  const h = l.match(/^@@ -\\d+(?:,\\d+)? \\+(\\d+)/); if (h) { dong = +h[1]; continue; }\n  if (l.startsWith('+')) { so++; for (const [muc, re, nhac] of LUAT) if (re.test(l)) bat.push({ muc, o: `${tep.split('/').pop()}:${dong}`, nhac }); dong++; }\n  else if (!l.startsWith('-')) dong++;\n}\nconsole.log(`soat-diff: ${so} dòng thêm, máy bắt được ${bat.length} chỗ`);\nfor (const b of bat) console.log(`  [${b.muc}] ${b.o}  ${b.nhac}`);\nconsole.log(`\nPHẦN NGƯỜI PHẢI SOÁT (máy không bắt được — mở ticket, đọc tiêu chí chấp nhận cạnh diff):\n  [ ] Đúng: mỗi AC của ticket có dòng mã thực hiện + có test? ca biên (rỗng, trùng, quá giờ)?\n  [ ] Quyền: mỗi truy vấn theo id có điều kiện \"của ai\" không? thử đổi id của người khác (IDOR — OWASP A01)\n  [ ] Đăng nhập: thiếu/sai người đăng nhập thì trả gì? (không được là 200)\n  [ ] Dữ liệu: trả về có trường nào người gọi không được thấy (ghi chú, SĐT, email người khác)?\n  [ ] Đầu vào: giá trị lạ (dấu nháy, chữ thay số, chuỗi rất dài) ⇒ 400, không phải 500\n  [ ] Dễ đọc: tên, hàm dài, chú thích \"vì sao\"; trùng lặp với mã đã có?\n  [ ] Hiệu năng: truy vấn trong vòng lặp (N+1), thiếu chỉ mục cho cột lọc mới?`);",
 "locNhanXet": "// loc-nhan-xet.mjs — soát một lượt review TRƯỚC khi bấm Submit: nhãn Conventional Comments, lý do + đề xuất, giọng, phán quyết.\n// Dùng: node loc-nhan-xet.mjs review/c2-v1.txt\n// Định dạng tệp: dòng đầu \"# … phán quyết: APPROVE|REQUEST_CHANGES|COMMENT\"; mỗi nhận xét mở bằng \"@ tệp:dòng\".\nimport fs from 'node:fs';\nconst [dau, ...khoi] = fs.readFileSync(process.argv[2], 'utf8').trim().split(/\\n(?=@ )/);\nconst phanQuyet = dau.match(/phán quyết:\\s*(\\w+)/)?.[1];\nconst NHAN = ['praise', 'nitpick', 'suggestion', 'issue', 'todo', 'question', 'thought', 'chore', 'note'];\nconst GIONG = [/sai rồi/i, /sao lại/i, /\\b(ông|bà|mày|cậu) lại\\b/i, /\\bngu\\b/i, /\\bdở\\b/i, /lần trước cũng/i, /luôn luôn|chẳng bao giờ/i, /rõ ràng là|chỉ cần|đơn giản là/i];\nconst LY_DO = /\\bvì\\b|⇒|\\bnên\\b|thử|output|\\bAC\\d?\\b|lộ|trả về|làm |gõ|thấy/i, DE_XUAT = /đề xuất|\\bdùng\\b|thêm|đổi|tách|bỏ|thay|```/i;\nlet chan = 0, khong = 0, khen = 0, loi = 0, nhac = 0, khongNhan = 0;\nfor (const k of khoi) {\n  const [o, ...than] = k.split('\\n'); const noiDung = than.join(' ').trim();\n  const m = noiDung.match(/^(\\w+)\\s*(?:\\(([^)]*)\\))?:\\s*(.*)$/s);\n  const v = [];\n  const nhan = m && NHAN.includes(m[1]) ? m[1] : null, trang = (m?.[2] ?? '').split(',').map((s) => s.trim());\n  const chuong = trang.includes('blocking') || (nhan === 'issue' && !trang.includes('non-blocking'));\n  if (!nhan) v.push(['✗', 'thiếu nhãn (issue/suggestion/question/nitpick/praise…) — người nhận không biết có phải sửa không']);\n  if (nhan === 'nitpick' && trang.includes('blocking')) v.push(['✗', 'nitpick không bao giờ chặn merge']);\n  if ((nhan === 'issue' || nhan === 'suggestion') && !DE_XUAT.test(m[3])) v.push(['⚠', 'chưa có đề xuất sửa cụ thể']);\n  if (nhan === 'issue' && !LY_DO.test(m[3])) v.push(['⚠', 'chưa nói vì sao / bằng chứng (output, AC, ca thử)']);\n  if (nhan === 'question' && !/\\?/.test(m[3])) v.push(['⚠', 'question mà không có câu hỏi']);\n  for (const g of GIONG) if (g.test(noiDung)) v.push(['⚠', `giọng: \"${noiDung.match(g)[0]}\" nhắm vào người, không vào mã`]);\n  if (noiDung.split(/\\s+/).length < 6 && nhan !== 'praise' && nhan !== 'nitpick') v.push(['⚠', 'quá ngắn để người nhận tự sửa mà không phải hỏi lại']);\n  if (!nhan) khongNhan++;\n  if (nhan === 'praise') khen++; else if (chuong) chan++; else if (nhan) khong++;\n  loi += v.filter((x) => x[0] === '✗').length; nhac += v.filter((x) => x[0] === '⚠').length;\n  console.log(`${o.slice(2).padEnd(18)} ${v.length ? v[0][0] : '✓'} ${nhan ? nhan + (chuong ? ' [chặn]' : '') : '(không nhãn)'}: ${noiDung.slice(nhan ? m[0].indexOf(m[3]) : 0).slice(0, 60)}${noiDung.length > 60 ? '…' : ''}`);\n  for (const [k2, s] of v) console.log(`${' '.repeat(20)}${k2} ${s}`);\n}\nconsole.log(`tổng: ${khoi.length} nhận xét — ${chan} chặn, ${khong} không chặn, ${khen} khen; phán quyết ${phanQuyet}`);\nif (phanQuyet === 'APPROVE' && chan) { console.log(`  ✗ APPROVE nhưng có ${chan} nhận xét chặn — hoặc đổi sang REQUEST_CHANGES, hoặc hạ mức các nhận xét đó`); loi++; }\nif (phanQuyet === 'APPROVE' && khongNhan) { console.log(`  ⚠ APPROVE kèm ${khongNhan} nhận xét không nhãn — tác giả được quyền merge ngay mà không sửa gì; nếu có chỗ PHẢI sửa thì đó là REQUEST_CHANGES`); nhac++; }\nif (phanQuyet === 'REQUEST_CHANGES' && !chan) { console.log('  ⚠ REQUEST_CHANGES mà không có nhận xét chặn nào — người nhận không biết phải sửa gì mới được merge'); nhac++; }\nif (!khen) console.log('  · không có praise nào — có chỗ nào làm tốt đáng nói không?');\nconsole.log(`loc-nhan-xet: ${loi} lỗi, ${nhac} nhắc`);\nprocess.exit(loi ? 1 : 0);",
 "c2v1": "# PR #31 feat(LF-23): lịch của tôi (S23) — tác giả C1 (trưởng nhóm), review C2 — phán quyết: APPROVE\n@ DatLichApi.java:27\nsai rồi, sửa đi\n@ DatLichApi.java:30\nSao lại viết thế này??\n@ DatLichApi.java:34\nÔng lại để lộ lỗi ra ngoài, lần trước cũng thế\n@ DatLichApi.java:16\nđổi println sang logger\n@ DatLichApi.java:21\nbiến duong đặt tên dở quá\n@ DatLichApi.java:1\nNhìn chung ok, approve trước cho kịp demo thứ sáu",
 "c2v2": "# PR #31 feat(LF-23): lịch của tôi (S23) — tác giả C1 (trưởng nhóm), review C2 — phán quyết: REQUEST_CHANGES\n@ DatLichApi.java:27\nissue (blocking, bảo mật): Giá trị lab được nối thẳng vào SQL. Mình thử gõ LAB-1' or '1'='1 thì API trả cả 4 lịch của mọi người (output dán bên dưới). Đề xuất dùng PreparedStatement với ? cho cả uid và lab.\n@ DatLichApi.java:30\nissue (blocking, bảo mật): Lấy lịch theo id mà không kiểm chủ: An (2201) đổi số thành 102 là đọc được lịch và ghi chú riêng của Bình. AC2 của LF-23 ghi \"chỉ chủ lịch hoặc quản lý lab xem chi tiết\". Đề xuất thêm điều kiện nguoi_dat_id = ? (hoặc vai QUAN_LY_LAB), không khớp thì trả 404.\n@ DatLichApi.java:34\nissue (blocking): e.getMessage() trả nguyên lỗi CSDL cho người gọi — gõ một dấu nháy là thấy cả câu SQL và tên cột. Đề xuất ghi log phía máy chủ, trả {\"loi\":\"lỗi hệ thống\"}.\n@ DatLichApi.java:20\nquestion (non-blocking): Khi thiếu header đăng nhập, uid thành null và API trả 200 với mảng rỗng. Mình nghĩ nên trả 401 để FE biết chuyển về trang đăng nhập — anh thấy sao?\n@ DatLichApi.java:40\nsuggestion (non-blocking): Ghi chú của lịch 104 có dấu \" nên JSON trả về bị vỡ (python json.tool báo lỗi cột 93). Đề xuất thoát chuỗi, hoặc dùng Jackson như các API khác của nhóm.\n@ DatLichApi.java:16\nnitpick: println → logger của dự án.\n@ DatLichApi.java:46\npraise: Tách tra() và json() ra hàm riêng làm phần xử lý chính rất dễ đọc — mình sẽ làm theo cách này cho S20.",
 "traLoi": "// tra-loi.mjs — trưởng nhóm (hoặc chính tác giả) soát các luồng review của một PR: ai đang chờ ai, luồng nào bị đóng sai,\n// luồng nào cãi quá lâu. Dùng: node tra-loi.mjs review/luong-v1.json\nimport fs from 'node:fs';\nconst P = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));\nconst gio = (a, b) => Math.round((new Date(b) - new Date(a)) / 36e5);\nconst hash = /\\b[0-9a-f]{7,40}\\b/, DE_SAU = /để sau|sau này|later/i;\nlet loi = 0, nhac = 0, conChan = 0;\nconsole.log(`PR #${P.pr} — tác giả ${P.tacGia}, review ${P.review}; soát lúc ${P.bayGio.replace('T', ' ')}`);\nfor (const t of P.luong) {\n  const v = [], tg = t.tin.filter((x) => x.ai === P.tacGia), vong = t.tin.filter((x, i) => i && x.ai !== t.tin[i - 1].ai).length;\n  if (t.nhan === 'praise') { console.log(`  ${t.o.padEnd(18)} ✓ praise`); continue; }\n  if (!tg.length) v.push(['⚠', `tác giả chưa trả lời sau ${gio(t.mo, P.bayGio)} giờ (thoả thuận: trong 1 ngày làm việc)`]);\n  if (t.chan && t.dongBoi === P.tacGia) v.push(['✗', 'luồng CHẶN do tác giả tự đóng — chỉ người review đóng luồng chặn']);\n  if (t.dongBoi && tg.length && /^(ok|done|xong|đã sửa)\\.?$/i.test(tg.at(-1).noi.trim())) v.push(['⚠', '\"ok\" trơn — ghi sửa ở commit nào (hash) hoặc vì sao không sửa']);\n  if (tg.some((x) => DE_SAU.test(x.noi) && !/LF-\\d+/.test(x.noi))) v.push(['⚠', '\"để sau\" không kèm mã ticket = không bao giờ']);\n  if (vong > 3) v.push(['⚠', `${vong} lượt qua lại — dừng gõ, gọi 10 phút, ghi kết luận vào luồng`]);\n  if (t.chan && !t.dongBoi) conChan++;\n  if (t.chan && t.dongBoi === P.tacGia) conChan++;\n  const trangThai = t.dongBoi ? `đóng bởi ${t.dongBoi}` : 'đang mở';\n  const cuoi = tg.at(-1)?.noi ?? '(chưa trả lời)';\n  console.log(`  ${t.o.padEnd(18)} ${v.length ? (v.some((x) => x[0] === '✗') ? '✗' : '⚠') : '✓'} ${t.nhan}${t.chan ? ' [chặn]' : ''}, ${trangThai} — ${P.tacGia}: ${cuoi.slice(0, 58)}${cuoi.length > 58 ? '…' : ''}`);\n  for (const [k, s] of v) console.log(`${' '.repeat(22)}${k} ${s}`);\n  loi += v.filter((x) => x[0] === '✗').length; nhac += v.filter((x) => x[0] === '⚠').length;\n}\nconsole.log(`tra-loi: ${loi} lỗi, ${nhac} nhắc; luồng chặn chưa được người review đóng: ${conChan} ⇒ ${conChan || loi ? 'CHƯA merge được' : 'đủ điều kiện merge (nếu CI xanh)'}`);\nprocess.exit(conChan || loi ? 1 : 0);",
 "aiDuyet": "// ai-duyet.mjs — MÔ HÌNH ĐỒ CHƠI (hạt giống cố định): ba cách chia người review cho iteration 2 của LabFlow (20 ngày làm việc, 30 PR).\n// Giả định ghi rõ: mỗi người đọc kỹ được ~300 dòng/ngày ngoài giờ code; PR xếp hàng theo thứ tự mở; review xong ⇒ sửa 1 ngày ⇒ merge.\n// Số tuyệt đối phụ thuộc giả định; thứ cần đọc là CHIỀU của khác biệt. Dùng: node ai-duyet.mjs [dòng/ngày] [ngày C1 vắng, vd 8,9,10]\nconst NHOM = ['C1', 'C2', 'C3', 'C4', 'C5'];\nconst MIEN = { C1: 'dat-lich', C2: 'lab', C3: 'tai-khoan', C4: 'muon-tra', C5: 'nguoi-dung' };\nconst SUC = +(process.argv[2] ?? 300), NGAY = 20;\nconst VANG = process.argv[3] ? { C1: process.argv[3].split(',').map(Number) } : {};   // vd \"8,9,10\": C1 đi thi 3 ngày\nlet h = 20270215; const r = () => ((h = (h * 1103515245 + 12345) % 2147483648) / 2147483648);\nconst PR = [];\nfor (const [i, ai] of NHOM.entries()) for (let k = 0; k < 6; k++)\n  PR.push({ id: PR.length + 1, ai, mien: MIEN[ai], mo: Math.min(18, 1 + ((i + 3 * k + Math.floor(r() * 2)) % 18)), dong: 60 + Math.floor(r() * 290) });\nPR.sort((a, b) => a.mo - b.mo || a.id - b.id);\nconst CACH = {\n  'A. trưởng nhóm duyệt hết': (p) => (p.ai === 'C1' ? 'C2' : 'C1'),\n  'B. xoay vòng cố định': (p) => NHOM[(NHOM.indexOf(p.ai) + 1) % 5],\n  'C. xoay vòng, đổi cặp mỗi tuần': (p) => NHOM[(NHOM.indexOf(p.ai) + 1 + (Math.floor((p.mo - 1) / 5) % 4)) % 5],\n};\nconst pct = (a, q) => [...a].sort((x, y) => x - y)[Math.min(a.length - 1, Math.floor(q * a.length))];\nfor (const [ten, chon] of Object.entries(CACH)) {\n  const hang = Object.fromEntries(NHOM.map((n) => [n, []])), tai = Object.fromEntries(NHOM.map((n) => [n, 0]));\n  const biet = Object.fromEntries(Object.values(MIEN).map((m) => [m, new Set()]));\n  for (const p of PR) { p.rv = chon(p); biet[p.mien].add(p.ai).add(p.rv); tai[p.rv] += p.dong; }\n  const xong = {}, con = Object.fromEntries(PR.map((p) => [p.id, p.dong]));\n  for (let d = 1; d <= 40; d++) for (const n of NHOM) {\n    if (VANG[n]?.includes(d)) continue;                 // vắng: không review được ngày đó\n    let suc = SUC;\n    for (const p of PR.filter((x) => x.rv === n && x.mo <= d && !xong[x.id])) {\n      const doc = Math.min(suc, con[p.id]); con[p.id] -= doc; suc -= doc;\n      if (con[p.id] === 0) xong[p.id] = d; else break;\n    }\n  }\n  const cho = PR.map((p) => xong[p.id] - p.mo), merge = PR.map((p) => xong[p.id] + 1);\n  const it2Tre = merge.filter((m) => m > NGAY).length, cuoi = merge.filter((m) => m >= NGAY - 2 && m <= NGAY).length;\n  console.log(`\\n${ten}`);\n  console.log(`  chờ review (ngày): trung vị ${pct(cho, 0.5)}, p85 ${pct(cho, 0.85)}, lâu nhất ${Math.max(...cho)}; tổng PR-ngày chờ ${cho.reduce((s, x) => s + x, 0)}`);\n  console.log(`  merge trong 3 ngày cuối: ${cuoi}/30; lọt sang sau hạn iteration: ${it2Tre}/30`);\n  console.log(`  dòng phải đọc: ${NHOM.map((n) => `${n} ${tai[n]}`).join(' · ')}`);\n  console.log(`  mỗi miền mấy người đã đọc mã: ${Object.entries(biet).map(([m, s]) => `${m} ${s.size}`).join(' · ')}`);\n}\nconsole.log(`\\n(30 PR, tổng ${PR.reduce((s, p) => s + p.dong, 0)} dòng; sức đọc ${SUC} dòng/người/ngày; iteration ${NGAY} ngày làm việc${VANG.C1 ? `; C1 vắng ngày ${VANG.C1.join(', ')}` : ''})`);",
 "kiemDuyet": "// kiem-duyet.mjs — mô phỏng luật bảo vệ main của LabFlow trên danh sách PR (thứ GitHub làm khi bật: 1 approval, review của\n// Code Owners, bỏ approval cũ khi có commit mới, mọi luồng phải được đóng, check CI bắt buộc). Dùng: node kiem-duyet.mjs mau/CODEOWNERS mau/pr.json\nimport fs from 'node:fs';\nconst luat = fs.readFileSync(process.argv[2], 'utf8').split('\\n').map((l) => l.trim()).filter((l) => l && !l.startsWith('#'))\n  .map((l) => { const [mau, ...chu] = l.split(/\\s+/); return { mau, chu: chu.map((c) => c.slice(1).toUpperCase()) }; });\nconst khop = (mau, f) => (mau.endsWith('/') ? ('/' + f).startsWith(mau) : '/' + f === mau);\nconst chuCua = (f) => luat.filter((l) => khop(l.mau, f)).at(-1)?.chu ?? [];   // dòng khớp sau cùng thắng\nfor (const p of JSON.parse(fs.readFileSync(process.argv[3], 'utf8'))) {\n  const v = [], hopLe = p.duyet.filter((d) => d.ai !== p.tacGia && d.trangThai === 'APPROVED' && !d.cu);\n  if (p.duyet.some((d) => d.trangThai === 'APPROVED' && d.cu)) v.push(`approval của ${p.duyet.filter((d) => d.cu).map((d) => d.ai).join(', ')} đã cũ (có commit mới sau khi duyệt) — bị bỏ`);\n  if (!hopLe.length) v.push('chưa có approval hợp lệ nào');\n  for (const d of p.duyet.filter((x) => x.trangThai === 'CHANGES_REQUESTED')) v.push(`${d.ai} đang REQUEST_CHANGES`);\n  const canChu = new Map();\n  for (const f of p.tep) { const c = chuCua(f).filter((x) => x !== p.tacGia); if (c.length) canChu.set(f, c); }\n  for (const [f, c] of canChu) if (!hopLe.some((d) => c.includes(d.ai))) v.push(`${f} cần chủ ${c.join(' hoặc ')} duyệt`);\n  if (p.luongMo) v.push(`${p.luongMo} luồng review chưa đóng`);\n  if (p.ci !== 'xanh') v.push(`CI ${p.ci}`);\n  console.log(`#${p.pr} ${p.tieuDe} — ${p.tacGia}; duyệt: ${p.duyet.map((d) => `${d.ai} ${d.trangThai}${d.cu ? ' (cũ)' : ''}`).join(', ') || '(chưa ai)'}`);\n  console.log(v.length ? v.map((x) => `   ✗ ${x}`).join('\\n') + '\\n   ⇒ nút Merge KHOÁ' : '   ⇒ được merge');\n}",
 "codeowners": "# .github/CODEOWNERS của LabFlow — dòng khớp SAU CÙNG thắng (như GitHub). Chủ ở đây = người PHẢI duyệt khi PR chạm tệp đó.\n# Màn của ai người nấy giữ; người review thường lấy theo bảng xoay vòng (docs/xoay-vong.md), không ghi ở đây.\n/fe/src/modules/dat-lich/    @c1\n/fe/src/modules/lab/         @c2\n/fe/src/modules/tai-khoan/   @c3\n/fe/src/modules/muon-tra/    @c4\n/fe/src/modules/nguoi-dung/  @c5\n# Tệp chung: hai chủ, để trưởng nhóm sửa vẫn có người khác duyệt\n/fe/src/menu.js              @c1 @c2\n/fe/src/routes.js            @c1 @c2\n/be/db/migration/            @c1 @c3\n/ci/                         @c1 @c3\n/.github/                    @c1 @c3",
 "prJson": "[\n {\"pr\": 31, \"tieuDe\": \"feat(LF-23): lịch của tôi (S23)\", \"tacGia\": \"C1\", \"tep\": [\"be/src/DatLichApi.java\", \"fe/src/modules/dat-lich/pages/S23.js\"],\n  \"duyet\": [{\"ai\": \"C2\", \"trangThai\": \"APPROVED\"}], \"luongMo\": 0, \"ci\": \"xanh\"},\n {\"pr\": 32, \"tieuDe\": \"feat(LF-44): quầy cho mượn (S30)\", \"tacGia\": \"C4\", \"tep\": [\"fe/src/modules/muon-tra/pages/S30.js\", \"fe/src/modules/muon-tra/routes.js\", \"fe/src/menu.js\", \"fe/src/routes.js\", \"be/db/migration/V3__muon_tra.sql\"],\n  \"duyet\": [{\"ai\": \"C5\", \"trangThai\": \"APPROVED\"}], \"luongMo\": 0, \"ci\": \"xanh\"},\n {\"pr\": 33, \"tieuDe\": \"feat(LF-33): tìm phòng trống (S20)\", \"tacGia\": \"C2\", \"tep\": [\"fe/src/modules/dat-lich/pages/S20.js\", \"fe/src/modules/dat-lich/routes.js\"],\n  \"duyet\": [{\"ai\": \"C1\", \"trangThai\": \"APPROVED\", \"cu\": true}], \"luongMo\": 1, \"ci\": \"xanh\"},\n {\"pr\": 34, \"tieuDe\": \"chore(LF-02): giữ chỗ route + menu iteration 2\", \"tacGia\": \"C1\", \"tep\": [\"fe/src/menu.js\", \"fe/src/routes.js\", \"fe/src/modules/dat-lich/routes.js\"],\n  \"duyet\": [], \"luongMo\": 0, \"ci\": \"xanh\"},\n {\"pr\": 35, \"tieuDe\": \"fix(LF-12): thông báo sai mật khẩu (S03)\", \"tacGia\": \"C3\", \"tep\": [\"fe/src/modules/tai-khoan/pages/S03.js\"],\n  \"duyet\": [{\"ai\": \"C4\", \"trangThai\": \"APPROVED\"}, {\"ai\": \"C5\", \"trangThai\": \"CHANGES_REQUESTED\"}], \"luongMo\": 1, \"ci\": \"đỏ\"}\n]",
 "xoayVong": "// xoay-vong.mjs — bảng người review cho cả kỳ (3 iteration × 4 tuần): tuần w, người thứ i được review bởi người thứ (i + 1 + w mod 4) mod 5.\n// In bảng Markdown để dán vào docs/xoay-vong.md, rồi đếm: sau cả kỳ, mỗi người đã review mỗi người khác bao nhiêu tuần.\nconst N = ['C1', 'C2', 'C3', 'C4', 'C5'], TUAN = 12;\nconst rv = (i, w) => N[(i + 1 + (w % 4)) % 5];\nconsole.log('| Tuần | ' + N.map((n) => `PR của ${n}`).join(' | ') + ' |');\nconsole.log('|---|' + N.map(() => '---').join('|') + '|');\nfor (let w = 0; w < TUAN; w++) if (w < 4 || w === TUAN - 1) console.log(`| ${w + 1} (it${Math.floor(w / 4) + 1}) | ` + N.map((_, i) => rv(i, w)).join(' | ') + ' |');\n  else if (w === 4) console.log('| … | (tuần 5–11 lặp lại chu kỳ 4 tuần) |||||');\nconst dem = {};\nfor (let w = 0; w < TUAN; w++) N.forEach((a, i) => { const k = `${rv(i, w)}→${a}`; dem[k] = (dem[k] ?? 0) + 1; });\nconst so = Object.values(dem);\nconsole.log(`\\n${Object.keys(dem).length}/20 cặp (người review → tác giả) có xuất hiện; mỗi cặp ${Math.min(...so)}–${Math.max(...so)} tuần; không ai tự review mình: ${Object.keys(dem).every((k) => k.split('→')[0] !== k.split('→')[1])}`);\nfor (const n of N) console.log(`  ${n} review: ${N.filter((x) => x !== n).map((x) => `${x} ${dem[`${n}→${x}`] ?? 0} tuần`).join(', ')}`);",
 "kbBaoMat": "#!/bin/bash\n# kb-bao-mat.sh — bài 4.4: hai lỗi mà review phải bắt (IDOR + SQL injection) trên API \"Lịch của tôi\", bản v1 (mở PR) và v2 (sau review).\n# PostgreSQL 16 trong container agt-pg4 (giới hạn 2g/2 CPU, dữ liệu trên tmpfs) — tự dựng, tự xoá.\nset -u; G=$(cd \"$(dirname \"$0\")\" && pwd); CP=$(tr ':' '\\n' < \"$G/../ch3/ci-java/cp.txt\" | grep postgresql-42)\ndocker rm -f agt-pg4 >/dev/null 2>&1\ndocker run -d --name agt-pg4 --memory 2g --memory-swap 2g --cpus 2 -p 127.0.0.1:45434:5432 -e POSTGRES_HOST_AUTH_METHOD=trust \\\n  --tmpfs /var/lib/postgresql/data postgres:16 >/dev/null\nuntil docker exec agt-pg4 pg_isready -q -h 127.0.0.1 2>/dev/null; do sleep 1; done; sleep 1\ndocker exec -i agt-pg4 psql -q -U postgres -h 127.0.0.1 < \"$G/du-lieu.sql\"\ngoi() { printf '$ curl -s %s\"%s\"\\n' \"${2:+-H 'X-Nguoi-Dung: $2' }\" \"localhost:45441$1\"\n  curl -s -w '   [HTTP %{http_code}]\\n' ${2:+-H \"X-Nguoi-Dung: $2\"} \"http://127.0.0.1:45441$1\"; }\nfor v in v1 v2; do\n  ( cd \"$G/$v\" && exec java -Dstdout.encoding=UTF-8 -Dstderr.encoding=UTF-8 -cp \"$CP\" DatLichApi.java 45441 ) > \"$G/may-chu-$v.log\" 2>&1 &\n  J=$!; until curl -s -o /dev/null http://127.0.0.1:45441/api/dat-lich/0 2>/dev/null; do sleep 0.5; done\n  {\n    echo \"# $(head -1 $G/may-chu-$v.log) — An (2201) đăng nhập\"\n    echo \"## 1. Việc bình thường: lịch của tôi ở LAB-1, chi tiết lịch 101 của chính tôi\"\n    goi '/api/dat-lich/tim?lab=LAB-1' 2201\n    goi '/api/dat-lich/101' 2201\n    echo \"## 2. Đổi số trên URL: An xem lịch 102 của Bình\"\n    goi '/api/dat-lich/102' 2201\n    echo \"## 3. Gõ vào ô lab:  LAB-1' or '1'='1\"\n    goi \"/api/dat-lich/tim?lab=LAB-1'%20or%20'1'='1\" 2201\n    echo \"## 4. Quên header đăng nhập\"\n    goi '/api/dat-lich/tim?lab=LAB-1'\n    echo \"## 5. Gõ một dấu nháy vào ô lab:  LAB-1'\"\n    goi \"/api/dat-lich/tim?lab=LAB-1'\" 2201\n    echo \"## 6. Quản lý lab (901) xem lịch 102 — được phép theo BR-07\"\n    goi '/api/dat-lich/102' 901\n    echo \"## 7. Lịch của tôi ở LAB-2 — ghi chú do An gõ có dấu nháy kép; kết quả có còn là JSON?\"\n    goi '/api/dat-lich/tim?lab=LAB-2' 2201\n    echo \"\\$ curl -s -H 'X-Nguoi-Dung: 2201' \\\"localhost:45441/api/dat-lich/tim?lab=LAB-2\\\" | python3 -m json.tool > /dev/null && echo JSON hợp lệ\"\n    curl -s -H 'X-Nguoi-Dung: 2201' \"http://127.0.0.1:45441/api/dat-lich/tim?lab=LAB-2\" | python3 -m json.tool 2>&1 >/dev/null && echo JSON hợp lệ\n  } > \"$G/out-bao-mat-$v.txt\"\n  kill $J; wait $J 2>/dev/null\n  [ -s \"$G/may-chu-$v.log\" ] && { echo \"## log máy chủ $v:\"; cat \"$G/may-chu-$v.log\"; } >> \"$G/out-bao-mat-$v.txt\"\ndone\ndocker rm -f agt-pg4 >/dev/null; rm -f \"$G\"/may-chu-v?.log\ndiff -u v1/DatLichApi.java v2/DatLichApi.java | sed '1,2s/\\t.*//' > out-diff-v1-v2.txt\necho xong; docker ps -a --format '{{.Names}}' | grep -c agt-pg4 || true",
 "baiTap41": "// bai-tap-41.mjs — đáp án bài tập 4.1: (1) quét tốc độ đọc khi C1 vắng ngày 8–10; (2) thêm cách D \"xoay vòng đổi cặp + C1 duyệt thêm mọi PR\".\n// Cùng giả định và hạt giống với ai-duyet.mjs; PR cần NHIỀU người review thì merge sau khi người chậm nhất đọc xong.\nconst NHOM = ['C1', 'C2', 'C3', 'C4', 'C5'], NGAY = 20;\nfunction chay(SUC, vang, chon) {\n  let h = 20270215; const r = () => ((h = (h * 1103515245 + 12345) % 2147483648) / 2147483648);\n  const PR = [];\n  for (const [i, ai] of NHOM.entries()) for (let k = 0; k < 6; k++)\n    PR.push({ id: PR.length + 1, ai, mo: Math.min(18, 1 + ((i + 3 * k + Math.floor(r() * 2)) % 18)), dong: 60 + Math.floor(r() * 290) });\n  PR.sort((a, b) => a.mo - b.mo || a.id - b.id);\n  const viec = PR.flatMap((p) => chon(p).map((rv) => ({ p, rv, con: p.dong })));\n  const xong = {};\n  for (let d = 1; d <= 60; d++) for (const n of NHOM) {\n    if (n === 'C1' && vang.includes(d)) continue;\n    let suc = SUC;\n    for (const v of viec.filter((x) => x.rv === n && x.p.mo <= d && x.con > 0)) {\n      const doc = Math.min(suc, v.con); v.con -= doc; suc -= doc;\n      if (v.con === 0) xong[v.p.id] = Math.max(xong[v.p.id] ?? 0, d); else break;\n    }\n  }\n  const cho = PR.map((p) => xong[p.id] - p.mo).sort((a, b) => a - b);\n  return { tv: cho[15], tre: PR.filter((p) => xong[p.id] + 1 > NGAY).length, c1: viec.filter((v) => v.rv === 'C1').reduce((s, v) => s + v.p.dong, 0) };\n}\nconst A = (p) => [p.ai === 'C1' ? 'C2' : 'C1'];\nconst C = (p) => [NHOM[(NHOM.indexOf(p.ai) + 1 + (Math.floor((p.mo - 1) / 5) % 4)) % 5]];\nconst D = (p) => [...new Set([...C(p), p.ai === 'C1' ? 'C2' : 'C1'])].filter((x) => x !== p.ai);\nconsole.log('(1) cách A, C1 vắng ngày 8–10 — dòng/ngày: chờ trung vị, PR trễ hạn');\nfor (const s of [300, 275, 250, 225, 200, 175, 150]) { const k = chay(s, [8, 9, 10], A); console.log(`    ${s}: ${k.tv} ngày, ${k.tre}/30 trễ`); }\nconsole.log('(2) 150 dòng/ngày, C1 vắng ngày 8–10:');\nfor (const [ten, f] of [['A', A], ['C', C], ['D', D]]) { const k = chay(150, [8, 9, 10], f); console.log(`    ${ten}: chờ trung vị ${k.tv} ngày, ${k.tre}/30 trễ, C1 phải đọc ${k.c1} dòng`); }",
 "bt42de": "# PR #32 feat(LF-44): quầy cho mượn (S30) — tác giả C4, review C5 — phán quyết: APPROVE\n@ S30.js:14\nsao không kiểm thiết bị đang mượn?\n@ V3__muon_tra.sql:1\nchỉ cần thêm unique là xong\n@ S30.js:3\nok",
 "bt42giai": "# PR #32 feat(LF-44): quầy cho mượn (S30) — tác giả C4, review C5 — phán quyết: REQUEST_CHANGES\n@ S30.js:14\nissue (blocking): Cho mượn không kiểm trạng thái thiết bị. Mình thử cho SV 2201 mượn TB-007 hai lần liên tiếp thì có hai dòng muon_tra đang mở — trái AC2 của LF-44 (phải trả 409). Đề xuất kiểm trang_thai = SAN_SANG trong cùng giao dịch trước khi ghi.\n@ V3__muon_tra.sql:1\nsuggestion (non-blocking): Thêm chỉ mục unique một phần trên muon_tra(thiet_bi_id) where tra_luc is null để CSDL tự chặn khi hai người bấm cùng lúc, vì kiểm ở service vẫn có khe giữa đọc và ghi.\n@ S30.js:3\npraise: Thông báo lỗi bằng lời của kỹ thuật viên (\"Thiết bị đang được mượn\") rất rõ, không lộ mã lỗi.",
 "baiTap44": "// bai-tap-44.mjs = soat-diff.mjs + MỘT luật mới (đáp án bài tập 4.4): truy vấn lấy theo id mà không có điều kiện thứ hai.\n// soat-diff.mjs — người review chạy TRƯỚC khi đọc PR: máy bắt phần máy bắt được trên các dòng THÊM của diff,\n// rồi in phần checklist mà chỉ NGƯỜI soát được (đối chiếu tiêu chí chấp nhận, quyền, dữ liệu).\n// Dùng: git diff origin/main... | node soat-diff.mjs      hoặc   node soat-diff.mjs <tệp.diff>\nimport fs from 'node:fs';\nconst diff = fs.readFileSync(process.argv[2] ?? 0, 'utf8').split('\\n');\nconst LUAT = [   // [mức, mẫu, lời nhắc] — mẫu đơn giản, cố ý: bắt nhiều hơn là sót; người review quyết định\n  ['blocking', /\"(select|insert|update|delete)\\b[^\"]*\"\\s*\\+|\\+\\s*\"[^\"]*'\"\\s*\\+|'\"\\s*\\+\\s*\\w+\\s*\\+\\s*\"'/i, 'nối chuỗi vào câu SQL ⇒ SQL injection; dùng PreparedStatement / tham số ?'],\n  ['blocking', /\\.createStatement\\(\\)/, 'Statement thường: mọi giá trị phải đi qua tham số — xem lại các câu SQL dùng nó'],\n  ['blocking', /getMessage\\(\\)[^;]*\\b(tra|send|write|body|ResponseEntity)|\\b(tra|send|write|body)\\([^;]*getMessage\\(\\)/, 'trả thông báo lỗi nội bộ cho người gọi ⇒ lộ câu SQL/cấu trúc bảng; ghi log, trả câu chung'],\n  ['blocking', /(password|passwd|secret|api[_-]?key|token)\\s*[=:]\\s*[\"'][^\"']{6,}/i, 'có vẻ là bí mật viết thẳng trong mã'],\n  ['blocking', /where\\s+id\\s*=\\s*(\\?|\"\\s*\\+)(?![^\"]*\\band\\b)/i, 'lấy bản ghi CHỈ theo id, không kèm điều kiện chủ/quyền ⇒ nghi IDOR; kiểm với tiêu chí chấp nhận'],\n  ['non-blocking', /catch\\s*\\(\\s*(Exception|Throwable)\\s+\\w+\\s*\\)/, 'bắt Exception chung — có nuốt lỗi lập trình (NullPointer, NumberFormat) thành 500 không?'],\n  ['non-blocking', /String\\.format\\(\"\\{\\\\\"/, 'tự ghép JSON bằng String.format — giá trị chuỗi có được thoát \" và xuống dòng không?'],\n  ['non-blocking', /System\\.(out|err)\\.print|console\\.log|printStackTrace\\(\\)/, 'in ra console — dùng logger của dự án'],\n  ['non-blocking', /\\b(TODO|FIXME|XXX)\\b/, 'còn TODO — có ticket chưa?'],\n];\nlet tep = '', dong = 0, so = 0; const bat = [];\nfor (const l of diff) {\n  if (l.startsWith('+++ ')) { tep = l.slice(4).replace(/^b\\//, ''); continue; }\n  const h = l.match(/^@@ -\\d+(?:,\\d+)? \\+(\\d+)/); if (h) { dong = +h[1]; continue; }\n  if (l.startsWith('+')) { so++; for (const [muc, re, nhac] of LUAT) if (re.test(l)) bat.push({ muc, o: `${tep.split('/').pop()}:${dong}`, nhac }); dong++; }\n  else if (!l.startsWith('-')) dong++;\n}\nconsole.log(`soat-diff: ${so} dòng thêm, máy bắt được ${bat.length} chỗ`);\nfor (const b of bat) console.log(`  [${b.muc}] ${b.o}  ${b.nhac}`);\nconsole.log(`\nPHẦN NGƯỜI PHẢI SOÁT (máy không bắt được — mở ticket, đọc tiêu chí chấp nhận cạnh diff):\n  [ ] Đúng: mỗi AC của ticket có dòng mã thực hiện + có test? ca biên (rỗng, trùng, quá giờ)?\n  [ ] Quyền: mỗi truy vấn theo id có điều kiện \"của ai\" không? thử đổi id của người khác (IDOR — OWASP A01)\n  [ ] Đăng nhập: thiếu/sai người đăng nhập thì trả gì? (không được là 200)\n  [ ] Dữ liệu: trả về có trường nào người gọi không được thấy (ghi chú, SĐT, email người khác)?\n  [ ] Đầu vào: giá trị lạ (dấu nháy, chữ thay số, chuỗi rất dài) ⇒ 400, không phải 500\n  [ ] Dễ đọc: tên, hàm dài, chú thích \"vì sao\"; trùng lặp với mã đã có?\n  [ ] Hiệu năng: truy vấn trong vòng lặp (N+1), thiếu chỉ mục cho cột lọc mới?`);"
};
